Q: Is there a numpy (or scipy, or whatever) vectorized function that can sample from an array of probabilities? A: <pre><code>&quot;&quot;&quot;
Module Data Quality pour traiter les fichiers extraits de PGP.
Coordonne avec le module platform DQ pour la validation et génération de parquet.
&quot;&quot;&quot;

import re
import pandas as pd
import logging
from datetime import datetime
from pathlib import Path
from typing import List, Optional, Dict, Any

from modules.dq.data_quality import DQService as PlatformDQService

from models.processing_result import ProcessingResult
from models.table_config import TableConfig
from utils.config_loader import ConfigLoader
from utils.checksum_utils import ChecksumUtils
from trackers import ExecutionTracker, MockExecutionTracker


class DQProcessor:
    &quot;&quot;&quot;Processeur Data Quality pour les fichiers extraits de PGP.&quot;&quot;&quot;

    def __init__(self, config_loader: Optional[ConfigLoader] = None, tracker: Optional[ExecutionTracker] = None):
        &quot;&quot;&quot;
        Initialise le processeur DQ.

        Args:
            config_loader: Loader de configuration (optionnel)
            tracker: Tracker d'exécution pour idempotence (optionnel, défaut: MockExecutionTracker)
        &quot;&quot;&quot;
        self.config_loader = config_loader or ConfigLoader()
        self.platform_dq_service = PlatformDQService()
        self.tracker = tracker or MockExecutionTracker()
        self.logger = logging.getLogger(__name__)

    def process_extracted_files(self) -&gt; ProcessingResult:
        &quot;&quot;&quot;
        Traite tous les fichiers CSV extraits depuis le répertoire PGP extracted.

        Returns:
            ProcessingResult: Résultat global du traitement DQ
        &quot;&quot;&quot;
        try:
            # Charger la configuration
            settings = self.config_loader.config
            pgp_config = settings.get('pgp', {})
            dq_config = settings.get('data_quality', {})

            extracted_dir = pgp_config.get('extracted_dir', '/data/extracted')
            dq_out_dir = dq_config.get('output_dir', '/data/dq_out')
            dq_reports_dir = dq_config.get('reports_dir', '/data/dq_reports')

            self.logger.info(f&quot;Starting DQ processing from {extracted_dir}&quot;)

            # Découvrir les fichiers CSV extraits
            csv_files = self._discover_csv_files(extracted_dir)

            if not csv_files:
                return ProcessingResult(
                    success=True,
                    message=&quot;Aucun fichier CSV à traiter&quot;,
                    metadata={'extracted_dir': extracted_dir}
                )

            # Traiter chaque fichier CSV
            results = []
            for csv_file in csv_files:
                result = self._process_single_csv_file(
                    csv_file_path=csv_file,
                    dq_out_dir=dq_out_dir,
                    dq_reports_dir=dq_reports_dir
                )
                results.append(result)

                # Log du résultat intermédiaire
                if result.success:
                    self.logger.info(f&quot;✓ {Path(csv_file).name}: DQ processing completed&quot;)
                else:
                    self.logger.error(f&quot;✗ {Path(csv_file).name}: {result.error}&quot;)

            # Analyser les résultats globaux
            successful = [r for r in results if r.success]
            failed = [r for r in results if not r.success]

            if failed:
                return ProcessingResult(
                    success=False,
                    message=f&quot;Traitement DQ partiel: {len(successful)}/{len(results)} fichiers traités&quot;,
                    error=f&quot;{len(failed)} fichiers ont échoué&quot;,
                    metadata={
                        'extracted_dir': extracted_dir,
                        'dq_out_dir': dq_out_dir,
                        'total_files': len(csv_files),
                        'successful_files': len(successful),
                        'failed_files': len(failed),
                        'results': results
                    }
                )

            return ProcessingResult(
                success=True,
                message=f&quot;Traitement DQ réussi: {len(successful)} fichier(s) traité(s)&quot;,
                metadata={
                    'extracted_dir': extracted_dir,
                    'dq_out_dir': dq_out_dir,
                    'total_files': len(csv_files),
                    'successful_files': len(successful),
                    'results': results
                }
            )

        except Exception as e:
            error_msg = f&quot;Erreur critique lors du traitement DQ: {e}&quot;
            self.logger.error(error_msg, exc_info=True)
            return ProcessingResult(
                success=False,
                error=error_msg
            )

    def process_file(self, csv_file_path: str) -&gt; ProcessingResult:
        &quot;&quot;&quot;
        Traite un seul fichier CSV avec validation DQ.

        Méthode publique appelée par le pipeline coordinator et les commandes CLI.

        Args:
            csv_file_path: Chemin vers le fichier CSV à traiter

        Returns:
            ProcessingResult: Résultat du traitement DQ
        &quot;&quot;&quot;
        try:
            # Charger la configuration pour résoudre les répertoires
            settings = self.config_loader.config
            dq_config = settings.get('data_quality', {})

            dq_out_dir = dq_config.get('output_dir', '/data/dq_out')
            dq_reports_dir = dq_config.get('reports_dir', '/data/dq_reports')

            self.logger.info(f&quot;Processing single file: {csv_file_path}&quot;)

            # Déléguer au traitement interne
            return self._process_single_csv_file(
                csv_file_path=csv_file_path,
                dq_out_dir=dq_out_dir,
                dq_reports_dir=dq_reports_dir
            )

        except Exception as e:
            error_msg = f&quot;Erreur lors du traitement du fichier {csv_file_path}: {e}&quot;
            self.logger.error(error_msg, exc_info=True)
            return ProcessingResult(
                success=False,
                error=error_msg,
                metadata={'csv_file': csv_file_path}
            )

    def cleanup_temp_files(self, temp_dir: Optional[str] = None, max_age_hours: int = 72) -&gt; ProcessingResult:
        &quot;&quot;&quot;
        Nettoie les fichiers temporaires DQ (compatibilité pipeline).

        Si temp_dir est fourni, nettoie ce répertoire spécifique.
        Sinon, nettoie tous les répertoires DQ standard (output_dir et reports_dir).

        Args:
            temp_dir: Répertoire spécifique à nettoyer (optionnel)
            max_age_hours: Âge maximum des fichiers en heures (défaut: 72h)

        Returns:
            ProcessingResult: Résultat du nettoyage
        &quot;&quot;&quot;
        # Si un répertoire spécifique est fourni, nettoyer uniquement celui-ci
        if temp_dir:
            try:
                deleted_files = []
                if Path(temp_dir).exists():
                    deleted_files = self._cleanup_directory(temp_dir, max_age_hours)

                message = f&quot;Nettoyage DQ temp terminé: {len(deleted_files)} fichier(s) supprimé(s)&quot;
                self.logger.info(message)

                return ProcessingResult(
                    success=True,
                    message=message,
                    metadata={
                        'temp_dir': temp_dir,
                        'max_age_hours': max_age_hours,
                        'deleted_files': deleted_files
                    }
                )

            except Exception as e:
                error_msg = f&quot;Erreur lors du nettoyage de {temp_dir}: {e}&quot;
                self.logger.error(error_msg)
                return ProcessingResult(
                    success=False,
                    error=error_msg,
                    metadata={'temp_dir': temp_dir}
                )

        # Sinon, déléguer au nettoyage complet des répertoires DQ standard
        return self.cleanup_old_dq_files(max_age_hours=max_age_hours)

    def _process_single_csv_file(self,
                                csv_file_path: str,
                                dq_out_dir: str,
                                dq_reports_dir: str) -&gt; ProcessingResult:
        &quot;&quot;&quot;
        Traite un fichier CSV spécifique avec le module platform DQ.

        Args:
            csv_file_path: Chemin vers le fichier CSV
            dq_out_dir: Répertoire de sortie pour les parquets
            dq_reports_dir: Répertoire pour les rapports DQ

        Returns:
            ProcessingResult: Résultat du traitement
        &quot;&quot;&quot;
        try:
            csv_file = Path(csv_file_path)
            self.logger.info(f&quot;Processing CSV file: {csv_file.name}&quot;)

            # Créer les répertoires de sortie
            Path(dq_out_dir).mkdir(parents=True, exist_ok=True)
            Path(dq_reports_dir).mkdir(parents=True, exist_ok=True)

            # Déterminer le nom de la table à partir du fichier CSV
            table_name = self._extract_table_name(csv_file.name)

            # Vérifier si déjà traité (idempotence)
            # Note: on utilise le nom de fichier CSV pour tracker, car on n'a pas accès direct au fichier source PGP ici
            # Le fichier source PGP sera détecté dans le contexte du pipeline complet
            step_key = f&quot;DQ:{table_name}&quot;

            # Calculer checksum du CSV source
            input_checksum = ChecksumUtils.file_md5(csv_file)

            # Vérifier si déjà traité avec le même checksum
            # On pourrait utiliser le fichier source PGP si disponible dans le contexte
            # Pour l'instant on check par table_name (compatible avec exécution Autosys par table)
            if self.tracker.is_step_completed(table_name, step_key):
                existing_info = self.tracker.get_step_info(table_name, step_key)

                if existing_info and existing_info.get('input_checksum') == input_checksum:
                    output_path = existing_info.get('output_path')

                    if output_path and Path(output_path).exists():
                        self.logger.info(
                            f&quot;Table {table_name} already processed with same checksum, skipping&quot;
                        )
                        return ProcessingResult(
                            success=True,
                            message=f&quot;Already processed: {table_name}&quot;,
                            metadata={
                                'csv_file': csv_file_path,
                                'output_path': output_path,
                                'already_processed': True
                            }
                        )

            # Étape 1: Lire le CSV
            try:
                df = pd.read_csv(csv_file_path, delimiter='|', encoding='utf-8')
                self.logger.debug(f&quot;CSV loaded: {len(df)} rows, {len(df.columns)} columns&quot;)
            except pd.errors.EmptyDataError:
                self.logger.warning(f&quot;Empty CSV file: {csv_file.name}, skipping&quot;)
                return ProcessingResult(
                    success=True,
                    message=f&quot;Empty CSV file skipped: {csv_file.name}&quot;,
                    rows_processed=0,
                    metadata={'csv_file': csv_file_path, 'empty_file': True}
                )
            except UnicodeDecodeError:
                # Essayer avec un autre encodage
                df = pd.read_csv(csv_file_path, delimiter='|', encoding='iso-8859-1')
                self.logger.debug(f&quot;CSV loaded with iso-8859-1 encoding: {len(df)} rows&quot;)

            # Étape 2: Identifier la configuration de table (basée sur le nom du fichier)
            table_config = self._identify_table_config(csv_file.name)

            if not table_config:
                self.logger.warning(f&quot;No table configuration found for {csv_file.name}, using default&quot;)
                table_config = self._create_default_table_config(csv_file.name, df)

            # Étape 3: Appeler le module platform DQ
            self.logger.debug(f&quot;Calling platform DQ service for {csv_file.name}&quot;)
            dq_result = self.platform_dq_service.validate(df, table_config)

            # Étape 4: Traiter les résultats DQ
            if not dq_result.get('is_valid', False):
                error_msg = f&quot;Data Quality validation failed for {csv_file.name}&quot;
                self.logger.error(error_msg)

                # Sauvegarder le rapport d'erreur
                self._save_dq_report(csv_file.name, dq_result, dq_reports_dir, success=False)

                return ProcessingResult(
                    success=False,
                    error=error_msg,
                    metadata={
                        'csv_file': csv_file_path,
                        'dq_errors': dq_result.get('errors', [])
                    }
                )

            # Étape 5: Le module platform génère déjà le parquet, on le récupère
            valid_df = dq_result.get('valid_rows')
            if valid_df is None or len(valid_df) == 0:
                self.logger.warning(f&quot;No valid rows after DQ for {csv_file.name}&quot;)

            # Étape 6: Sauvegarder le parquet dans dq_out (conserve le nom original avec timestamp PGP)
            parquet_filename = f&quot;{csv_file.stem}.parquet&quot;
            parquet_path = Path(dq_out_dir) / parquet_filename

            if valid_df is not None and len(valid_df) &gt; 0:
                # Convertir les colonnes object avec des NaN en string pour éviter
                # ArrowTypeError (&quot;Expected bytes, got a 'float' object&quot;)
                for col in valid_df.columns:
                    if valid_df[col].dtype == 'object':
                        valid_df[col] = valid_df[col].fillna('').astype(str)
                valid_df.to_parquet(parquet_path, index=False)
                self.logger.info(f&quot;Parquet saved: {parquet_path}&quot;)
            else:
                # Créer un fichier parquet vide pour traçabilité
                empty_df = pd.DataFrame(columns=df.columns if not df.empty else [])
                empty_df.to_parquet(parquet_path, index=False)
                self.logger.warning(f&quot;Empty parquet saved: {parquet_path}&quot;)

            # Étape 7: Sauvegarder le rapport DQ
            self._save_dq_report(csv_file.name, dq_result, dq_reports_dir, success=True)

            # Marquer l'étape DQ comme complétée
            self.tracker.mark_step_completed(table_name, step_key, {
                'status': 'SUCCESS',
                'input_checksum': input_checksum,
                'output_path': str(parquet_path)
            })

            return ProcessingResult(
                success=True,
                message=f&quot;DQ processing completed for {csv_file.name}&quot;,
                rows_processed=len(df),
                metadata={
                    'csv_file': csv_file_path,
                    'parquet_file': str(parquet_path),
                    'valid_rows': len(valid_df) if valid_df is not None else 0,
                    'invalid_rows': len(dq_result.get('invalid_rows', [])) if dq_result.get('invalid_rows') is not None else 0,
                    'dq_report_path': str(Path(dq_reports_dir) / f&quot;{csv_file.stem}_dq_report.json&quot;)
                }
            )

        except Exception as e:
            error_msg = f&quot;Erreur lors du traitement DQ de {csv_file_path}: {e}&quot;
            self.logger.error(error_msg, exc_info=True)
            return ProcessingResult(
                success=False,
                error=error_msg,
                metadata={'csv_file': csv_file_path}
            )

    def _discover_csv_files(self, extracted_dir: str) -&gt; List[str]:
        &quot;&quot;&quot;Découvre tous les fichiers CSV dans le répertoire extrait.&quot;&quot;&quot;
        csv_files = []
        extracted_path = Path(extracted_dir)

        if not extracted_path.exists():
            self.logger.warning(f&quot;Extracted directory does not exist: {extracted_dir}&quot;)
            return []

        # Rechercher tous les fichiers CSV récursivement
        for csv_file in extracted_path.rglob(&quot;*.csv&quot;):
            csv_files.append(str(csv_file))

        csv_files.sort()  # Tri alphabétique pour un traitement déterministe
        self.logger.info(f&quot;Found {len(csv_files)} CSV files in {extracted_dir}&quot;)

        return csv_files

    @staticmethod
    def _extract_table_name(filename: str) -&gt; str:
        &quot;&quot;&quot;Extrait le nom de table en supprimant le timestamp du nom de fichier.

        Supporte: TABLE-YYYYMMDDHHmmss, TABLE_YYYYMMDD_HHMMSS, TABLE_YYYYMMDDHHmmss
        &quot;&quot;&quot;
        stem = Path(filename).stem

        # 1. Tiret + timestamp: NOM-YYYYMMDDTHHmmss ou NOM-YYYYMMDDHHmmss
        clean = re.sub(r'-\d{8}T?\d{6}$', '', stem)

        # 2. Underscore timestamps en boucle
        changed = True
        while changed:
            changed = False
            parts = clean.split('_')
            if len(parts) &gt;= 3:
                if (parts[-2].isdigit() and len(parts[-2]) == 8
                        and parts[-1].isdigit() and len(parts[-1]) == 6):
                    clean = '_'.join(parts[:-2])
                    changed = True
                    continue
            if len(parts) &gt;= 2:
                if parts[-1].isdigit() and len(parts[-1]) &gt;= 8:
                    clean = '_'.join(parts[:-1])
                    changed = True
                    continue

        return clean.upper()

    def _identify_table_config(self, filename: str) -&gt; Optional[TableConfig]:
        &quot;&quot;&quot;Identifie la configuration de table basée sur le nom de fichier.&quot;&quot;&quot;
        try:
            # Normaliser le nom de fichier : enlever extension et timestamps
            base_name = self._extract_table_name(filename)

            # Essayer de charger une configuration existante
            possible_table_names = [
                base_name,
                f&quot;T_{base_name}&quot;,
                base_name.replace('_', '')
            ]

            for table_name in possible_table_names:
                try:
                    table_config = self.config_loader.load_table_config(table_name)
                    if table_config:
                        self.logger.debug(f&quot;Found table config for {filename}: {table_name}&quot;)
                        return table_config
                except Exception:
                    continue

            return None

        except Exception as e:
            self.logger.debug(f&quot;Could not identify table config for {filename}: {e}&quot;)
            return None

    def _create_default_table_config(self, filename: str, df: pd.DataFrame) -&gt; TableConfig:
        &quot;&quot;&quot;Crée une configuration de table par défaut basée sur le DataFrame.&quot;&quot;&quot;
        base_name = self._extract_table_name(filename)

        # Inférer les types de colonnes
        columns = []
        for col_name in df.columns:
            data_type = &quot;VARCHAR&quot;
            nullable = True

            if not df[col_name].empty:
                if pd.api.types.is_numeric_dtype(df[col_name]):
                    data_type = &quot;NUMBER&quot;
                elif pd.api.types.is_datetime64_any_dtype(df[col_name]):
                    data_type = &quot;DATE&quot;

            columns.append({
                'name': col_name,
                'data_type': data_type,
                'nullable': nullable
            })

        config_data = {
            'data_contract': {
                'name': base_name,
                'description': f'Auto-generated contract for {base_name}',
                'critical': False,
                'version': 1.0,
                'owner': 'auto',
                'dataset': {
                    'format': {'column_delimiter': '|', 'with_header': True},
                    'primary_keys': [df.columns[0]] if len(df.columns) &gt; 0 else ['ID'],
                    'columns': columns
                }
            }
        }

        return TableConfig.from_dict(config_data)

    def _save_dq_report(self,
                       filename: str,
                       dq_result: Dict[str, Any],
                       reports_dir: str,
                       success: bool) -&gt; None:
        &quot;&quot;&quot;Sauvegarde le rapport de data quality.&quot;&quot;&quot;
        try:
            import json

            valid_rows_df = dq_result.get('valid_rows', [])
            invalid_rows_df = dq_result.get('invalid_rows')

            valid_count = len(valid_rows_df) if valid_rows_df is not None else 0
            invalid_count = len(invalid_rows_df) if invalid_rows_df is not None else 0

            report_data = {
                'filename': filename,
                'timestamp': datetime.now().isoformat(),
                'success': success,
                'is_valid': dq_result.get('is_valid', False),
                'total_rows': valid_count + invalid_count,
                'valid_rows': valid_count,
                'invalid_rows': invalid_count,
                'errors': dq_result.get('errors', []),
                'warnings': dq_result.get('warnings', [])
            }

            report_filename = f&quot;{Path(filename).stem}_dq_report.json&quot;
            report_path = Path(reports_dir) / report_filename

            with open(report_path, 'w', encoding='utf-8') as f:
                json.dump(report_data, f, indent=2, ensure_ascii=False)

            self.logger.debug(f&quot;DQ report saved: {report_path}&quot;)

        except Exception as e:
            self.logger.error(f&quot;Error saving DQ report for {filename}: {e}&quot;)

    def cleanup_old_dq_files(self,
                           max_age_hours: int = 72) -&gt; ProcessingResult:
        &quot;&quot;&quot;
        Nettoie les anciens fichiers DQ selon la politique de rétention.

        Args:
            max_age_hours: Âge maximum des fichiers en heures

        Returns:
            ProcessingResult: Résultat du nettoyage
        &quot;&quot;&quot;
        try:
            settings = self.config_loader.config
            dq_config = settings.get('data_quality', {})

            dq_out_dir = dq_config.get('output_dir', '/data/dq_out')
            dq_reports_dir = dq_config.get('reports_dir', '/data/dq_reports')

            deleted_files = []

            # Nettoyer les répertoires
            for directory in [dq_out_dir, dq_reports_dir]:
                if Path(directory).exists():
                    deleted_count = self._cleanup_directory(directory, max_age_hours)
                    deleted_files.extend(deleted_count)

            message = f&quot;Nettoyage DQ terminé: {len(deleted_files)} fichier(s) supprimé(s)&quot;
            self.logger.info(message)

            return ProcessingResult(
                success=True,
                message=message,
                metadata={
                    'dq_out_dir': dq_out_dir,
                    'dq_reports_dir': dq_reports_dir,
                    'max_age_hours': max_age_hours,
                    'deleted_files': deleted_files
                }
            )

        except Exception as e:
            error_msg = f&quot;Erreur lors du nettoyage DQ: {e}&quot;
            self.logger.error(error_msg)
            return ProcessingResult(
                success=False,
                error=error_msg
            )

    def _cleanup_directory(self, directory: str, max_age_hours: int) -&gt; List[str]:
        &quot;&quot;&quot;Nettoie les anciens fichiers d'un répertoire.&quot;&quot;&quot;
        deleted_files = []
        cutoff_time = datetime.now().timestamp() - (max_age_hours * 3600)

        try:
            for file_path in Path(directory).rglob(&quot;*&quot;):
                if file_path.is_file() and file_path.stat().st_mtime &lt; cutoff_time:
                    try:
                        file_path.unlink()
                        deleted_files.append(file_path.name)
                        self.logger.debug(f&quot;Fichier DQ supprimé: {file_path.name}&quot;)
                    except Exception as e:
                        self.logger.error(f&quot;Erreur suppression {file_path.name}: {e}&quot;)

        except Exception as e:
            self.logger.error(f&quot;Erreur lors du nettoyage de {directory}: {e}&quot;)

        return deleted_files

    def get_dq_statistics(self) -&gt; Dict[str, Any]:
        &quot;&quot;&quot;Récupère les statistiques des traitements DQ.&quot;&quot;&quot;
        try:
            settings = self.config_loader.config
            dq_config = settings.get('data_quality', {})

            dq_out_dir = dq_config.get('output_dir', '/data/dq_out')
            dq_reports_dir = dq_config.get('reports_dir', '/data/dq_reports')

            stats = {
                'dq_out_dir': dq_out_dir,
                'dq_reports_dir': dq_reports_dir,
                'parquet_files': 0,
                'total_parquet_size_mb': 0.0,
                'reports_count': 0,
                'latest_processing': None
            }

            # Compter les fichiers parquet
            if Path(dq_out_dir).exists():
                parquet_files = list(Path(dq_out_dir).glob(&quot;*.parquet&quot;))
                stats['parquet_files'] = len(parquet_files)

                total_size = sum(f.stat().st_size for f in parquet_files)
                stats['total_parquet_size_mb'] = round(total_size / (1024 * 1024), 2)

                if parquet_files:
                    latest_file = max(parquet_files, key=lambda f: f.stat().st_mtime)
                    stats['latest_processing'] = datetime.fromtimestamp(latest_file.stat().st_mtime).isoformat()

            # Compter les rapports
            if Path(dq_reports_dir).exists():
                report_files = list(Path(dq_reports_dir).glob(&quot;*.json&quot;))
                stats['reports_count'] = len(report_files)

            return stats

        except Exception as e:
            self.logger.error(f&quot;Erreur lors du calcul des statistiques DQ: {e}&quot;)
            return {'error': str(e)}
